// `hqplugin keys generate`: create the hybrid author key pair.
//
// Writes `ed25519.pem` and `ml-dsa-65.pem` (private; owner-only on POSIX) and
// `public-keys.json`, the two raw public keys the registry enrollment
// (authors/<slug>.json `public_keys`) wants. The private keys are generated by
// openssl straight into their files; this process never reads their contents
// and never prints them.
import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;

import 'author_signing.dart';

/// Generates the key pair in [outDir]. Exit codes: 64 usage, 65 a key file
/// already exists (nothing is ever overwritten) or [outDir] is not a
/// directory, 69 OpenSSL missing or too old, 70 an internal inconsistency.
Future<int> runKeysGenerate({
  required String? outDir,
  String? opensslPath,
  Map<String, String>? environment,
  StringSink? out_,
  StringSink? err_,
  OpenSslRunner runner = _runCommand,
}) async {
  final o = out_ ?? stdout;
  final e = err_ ?? stderr;
  if (outDir == null || outDir.isEmpty) {
    e.writeln('keys generate: --out <dir> is required.');
    return 64;
  }
  final dir = p.absolute(outDir);
  final edPath = p.join(dir, kEd25519KeyFile);
  final mlPath = p.join(dir, kMlDsa65KeyFile);
  final pubPath = p.join(dir, kPublicKeysFile);

  try {
    final tool = OpenSslTool(
      run: runner,
      executable: resolveOpenSslExecutable(
        opensslPath,
        environment ?? Platform.environment,
      ),
    );
    await tool.preflight();

    if (FileSystemEntity.typeSync(dir) != FileSystemEntityType.notFound &&
        FileSystemEntity.typeSync(dir) != FileSystemEntityType.directory) {
      e.writeln('keys generate: $dir exists and is not a directory.');
      return 65;
    }
    final existing = [
      for (final path in [edPath, mlPath, pubPath])
        if (FileSystemEntity.typeSync(path, followLinks: false) !=
            FileSystemEntityType.notFound)
          path,
    ];
    if (existing.isNotEmpty) {
      e.writeln(
        'keys generate: refusing to overwrite existing key material:\n'
        '${existing.map((f) => '  $f').join('\n')}\n'
        '  Choose another --out directory. (Overwriting a private key would '
        'lose the identity it enrolled.)',
      );
      return 65;
    }

    final created = !Directory(dir).existsSync();
    Directory(dir).createSync(recursive: true);
    // Only a directory made here is locked down; an existing one is the
    // user's own.
    if (created) await _chmod('700', dir);

    final written = <String>[];
    try {
      for (final (alg, path) in [
        (HybridAlgorithm.ed25519, edPath),
        (HybridAlgorithm.mlDsa65, mlPath),
      ]) {
        await tool.generateKey(alg, path);
        written.add(path);
        await _chmod('600', path);
      }
      final publicKeys = {
        for (final (alg, path) in [
          (HybridAlgorithm.ed25519, edPath),
          (HybridAlgorithm.mlDsa65, mlPath),
        ])
          alg.sigAlg: base64.encode(await tool.rawPublicKey(alg, path)),
      };
      final json =
          '${const JsonEncoder.withIndent('  ').convert(publicKeys)}\n';
      File(pubPath).writeAsStringSync(json);
      written.add(pubPath);

      o
        ..writeln(
          'keys: wrote the private keys. Keep them secret; never '
          'commit or share them:',
        )
        ..writeln('  $edPath')
        ..writeln('  $mlPath')
        ..writeln()
        ..writeln(
          'keys: wrote the public keys to $pubPath. Put them in your '
          'registry enrollment (authors/<slug>.json, public_keys):',
        )
        ..write(json)
        ..writeln()
        ..writeln('Custody:')
        ..writeln(
          '  - Back both .pem files up offline now. They cannot be '
          'recovered; losing them means enrolling new keys.',
        )
        ..writeln(
          '  - If a key leaks, ask the registry to revoke your '
          'enrollment ("revoked": true in authors/<slug>.json).',
        );
      if (Platform.isWindows) {
        o
          ..writeln(
            '  - Windows: file permissions were NOT restricted; the '
            'keys inherit the folder\'s access list. Restrict it, e.g.',
          )
          ..writeln(
            '      icacls "$dir" /inheritance:r /grant:r '
            '"%USERNAME%:(OI)(CI)F"',
          );
      }
      o
        ..writeln()
        ..writeln(
          'Next: enroll the public keys (see authors/README.md in '
          'https://github.com/HelloHQ/plugin-registry), then publish with '
          '`hqplugin publish --sign-key $dir`.',
        );
      return 0;
    } catch (_) {
      // A half-made pair is useless; remove only what this run created.
      for (final f in written) {
        try {
          File(f).deleteSync();
        } catch (_) {}
      }
      if (created) {
        try {
          Directory(dir).deleteSync();
        } catch (_) {}
      }
      rethrow;
    }
  } on SignerException catch (ex) {
    e.writeln('keys generate: ${ex.message}');
    return ex.code;
  }
}

/// `chmod` on POSIX; Windows has no mode bits (the caller prints the ACL note).
Future<void> _chmod(String mode, String path) async {
  if (Platform.isWindows) return;
  final r = await Process.run('chmod', [mode, path]);
  if (r.exitCode != 0) {
    throw SignerException(
      70,
      'could not restrict $path to mode $mode: ${r.stderr}',
    );
  }
}

Future<ProcessResult> _runCommand(String executable, List<String> arguments) =>
    Process.run(executable, arguments);
